// Build-time only. Reads the local Unicode Character Database inversion lists
// (Unicode 15.0 -- the same version the reference interpreter's unicodedata uses)
// and emits the compact runtime tables under /output/lib/unicode/data/.
import fs from 'node:fs';
import path from 'node:path';

const U = '/usr/share/perl/5.38.2/unicore';
const OUT = '/output/lib/unicode/data';
const MAX = 0x110000;

function parse(rel) {
  const t = fs.readFileSync(path.join(U, rel), 'utf8');
  const m = t.match(/return <<'END';\n([\s\S]*?)\nEND/);
  const lines = m[1].trim().split('\n');
  const v = lines.slice(1).map(Number);
  const r = [];
  for (let i = 0; i < v.length; i += 2) r.push([v[i], (i + 1 < v.length ? v[i + 1] : MAX) - 1]);
  return r;
}

// ---- set helpers (sorted, disjoint, inclusive ranges) ----
const setOf = (ranges) => { const b = new Uint8Array(0); return b; };
function toBits(ranges) {
  const b = new Uint8Array(MAX);
  for (const [a, z] of ranges) b.fill(1, a, z + 1);
  return b;
}
function bitsOfList(list) {
  const b = new Uint8Array(MAX);
  for (const [a, z] of list) b.fill(1, a, z + 1);
  return b;
}
function ranges(pred) {
  const out = [];
  let start = -1;
  for (let cp = 0; cp < MAX; cp++) {
    if (pred(cp)) { if (start < 0) start = cp; }
    else if (start >= 0) { out.push([start, cp - 1]); start = -1; }
  }
  if (start >= 0) out.push([start, MAX - 1]);
  return out;
}

// ---- source properties (Unicode 15.0) ----
const GC = {};
for (const g of ['Lu', 'Ll', 'Lt', 'Lm', 'Lo', 'Mn', 'Mc', 'Me', 'Nd', 'Nl', 'No', 'Cf', 'Cn', 'Sc', 'Sk', 'Sm', 'So', 'Pc', 'Pd', 'Pe', 'Pf', 'Pi', 'Po', 'Ps', 'Zs']) {
  GC[g] = toBits(parse(`lib/Gc/${g}.pl`));
}
const assigned = toBits(parse('lib/Perl/Assigned.pl'));
const cwkcf = toBits(parse('lib/CWKCF/Y.pl'));
const defIgn = toBits(parse('lib/DI/Y.pl'));
const virama = toBits(parse('lib/Ccc/VR.pl'));

const BIDI_CLASSES = ['AL', 'AN', 'B', 'BN', 'CS', 'EN', 'ES', 'ET', 'L', 'NSM', 'ON', 'R', 'WS'];
const bidi = new Uint8Array(MAX); // 0 = none/unassigned, else index+1
BIDI_CLASSES.forEach((name, i) => {
  for (const [a, z] of parse(`lib/Bc/${name}.pl`)) {
    for (let cp = a; cp <= z; cp++) if (assigned[cp]) bidi[cp] = i + 1;
  }
});

const JT = {};
for (const j of ['T', 'L', 'R', 'D']) JT[j] = toBits(parse(`lib/Jt/${j}.pl`));

const SCRIPTS = { Greek: 'Grek', Hebrew: 'Hebr', Hiragana: 'Hira', Katakana: 'Kana', Han: 'Han' };
const scriptBits = {};
for (const [name, file] of Object.entries(SCRIPTS)) scriptBits[name] = toBits(parse(`lib/Sc/${file}.pl`));

// Hangul_Syllable_Type in {L, V, T}: complement of NA, minus the LV/LVT syllable block.
const hstNA = toBits(parse('lib/Hst/NA.pl'));
const oldHangulJamo = (cp) => !hstNA[cp] && !(cp >= 0xac00 && cp <= 0xd7a3);

// ---- RFC 5892 derivation ----
const EXCEPTIONS = new Map();
for (const cp of [0x00df, 0x03c2, 0x06fd, 0x06fe, 0x0f0b, 0x3007]) EXCEPTIONS.set(cp, 'PVALID');
for (const cp of [0x00b7, 0x0375, 0x05f3, 0x05f4, 0x30fb]) EXCEPTIONS.set(cp, 'CONTEXTO');
for (let cp = 0x0660; cp <= 0x0669; cp++) EXCEPTIONS.set(cp, 'CONTEXTO');
for (let cp = 0x06f0; cp <= 0x06f9; cp++) EXCEPTIONS.set(cp, 'CONTEXTO');
for (const cp of [0x0640, 0x07fa, 0x302e, 0x302f, 0x3031, 0x3032, 0x3033, 0x3034, 0x3035, 0x303b]) EXCEPTIONS.set(cp, 'DISALLOWED');

const WHITE_SPACE = bitsOfList([[0x09, 0x0d], [0x20, 0x20], [0x85, 0x85], [0xa0, 0xa0], [0x1680, 0x1680], [0x2000, 0x200a], [0x2028, 0x2029], [0x202f, 0x202f], [0x205f, 0x205f], [0x3000, 0x3000]]);
const noncharacter = (cp) => (cp >= 0xfdd0 && cp <= 0xfdef) || (cp & 0xfffe) === 0xfffe;
const ignorableBlock = (cp) => (cp >= 0x20d0 && cp <= 0x20ff) || (cp >= 0x1d100 && cp <= 0x1d1ff) || (cp >= 0x1d200 && cp <= 0x1d24f);
const isLDH = (cp) => cp === 0x2d || (cp >= 0x30 && cp <= 0x39) || (cp >= 0x61 && cp <= 0x7a);
const isJoinControl = (cp) => cp === 0x200c || cp === 0x200d;
const isLetterDigit = (cp) => GC.Ll[cp] || GC.Lu[cp] || GC.Lo[cp] || GC.Nd[cp] || GC.Lm[cp] || GC.Mn[cp] || GC.Mc[cp];

function derive(cp) {
  if (EXCEPTIONS.has(cp)) return EXCEPTIONS.get(cp);
  if (!assigned[cp]) return 'UNASSIGNED';
  if (isLDH(cp)) return 'PVALID';
  if (isJoinControl(cp)) return 'CONTEXTJ';
  if (cwkcf[cp]) return 'DISALLOWED';
  if (defIgn[cp] || WHITE_SPACE[cp] || noncharacter(cp)) return 'DISALLOWED';
  if (ignorableBlock(cp)) return 'DISALLOWED';
  if (oldHangulJamo(cp)) return 'DISALLOWED';
  if (isLetterDigit(cp)) return 'PVALID';
  return 'DISALLOWED';
}

const cls = new Uint8Array(MAX); // 1 PVALID, 2 CONTEXTJ, 3 CONTEXTO
for (let cp = 0; cp < MAX; cp++) {
  const d = derive(cp);
  cls[cp] = d === 'PVALID' ? 1 : d === 'CONTEXTJ' ? 2 : d === 'CONTEXTO' ? 3 : 0;
}

// Patch: the reference idna tables are built from a newer UCD than the local one.
// `patches.json` is produced by the differential prober (gen/probe-*.mjs).
const patchFile = '/workspace/gen/patches.json';
if (fs.existsSync(patchFile)) {
  const patches = JSON.parse(fs.readFileSync(patchFile, 'utf8'));
  for (const [cpStr, v] of Object.entries(patches)) cls[Number(cpStr)] = v;
  console.log(`applied ${Object.keys(patches).length} table patches`);
}

// ---- compact serialisation: inversion list, base-36 deltas ----
function encodeRanges(rs) {
  let prev = 0;
  const parts = [];
  for (const [a, z] of rs) {
    parts.push((a - prev).toString(36));
    parts.push((z - a).toString(36));
    prev = z;
  }
  return parts.join(',');
}
const rangesOfBits = (bits, val = 1) => ranges((cp) => bits[cp] === val);

function emit(file, header, entries) {
  const body = entries.map(([name, rs]) => `export const ${name} = '${encodeRanges(rs)}';`).join('\n\n');
  fs.writeFileSync(path.join(OUT, file), `${header}\n${body}\n`);
  const bytes = fs.statSync(path.join(OUT, file)).size;
  console.log(`${file}: ${bytes} bytes`);
}

const H = (what) => `// Generated table -- ${what}.\n// Encoded as a base-36 delta inversion list; decode with rangesFromString() in ../ranges.mjs.\n`;

emit('idna-classes.mjs', H('IDNA2008 (RFC 5892) derived property values'), [
  ['PVALID', rangesOfBits(cls, 1)],
  ['CONTEXTJ', rangesOfBits(cls, 2)],
  ['CONTEXTO', rangesOfBits(cls, 3)],
]);

emit('bidi-classes.mjs', H('Bidi_Class, restricted to assigned code points'),
  BIDI_CLASSES.map((name, i) => [`BC_${name}`, rangesOfBits(bidi, i + 1)]));

emit('joining-types.mjs', H('Joining_Type'), ['T', 'L', 'R', 'D'].map((j) => [`JT_${j}`, rangesOfBits(JT[j])]));

emit('categories.mjs', H('General_Category M* and Canonical_Combining_Class=9 (Virama)'), [
  ['MARK', ranges((cp) => GC.Mn[cp] || GC.Mc[cp] || GC.Me[cp])],
  ['VIRAMA', rangesOfBits(virama)],
]);

emit('scripts.mjs', H('Script values needed by the CONTEXTO rules'),
  Object.keys(SCRIPTS).map((n) => [`SC_${n}`, rangesOfBits(scriptBits[n])]));

// Also emit a machine-readable dump used only by the differential prober.
const dump = { cls: Array.from(rangesOfBits(cls, 1)), contexto: Array.from(rangesOfBits(cls, 3)) };
fs.writeFileSync('/workspace/gen/derived-classes.json', JSON.stringify({
  pvalid: rangesOfBits(cls, 1), contextj: rangesOfBits(cls, 2), contexto: rangesOfBits(cls, 3),
  bidiAssigned: rangesOfBits(bidi, 0).length,
}));
console.log('BIDI_CLASSES order:', BIDI_CLASSES.join(','));

