/**
 * Inversion-list code point sets.
 *
 * The generated tables under ./data/ store each set as a base-36 delta encoded
 * inversion list: pairs of (gap from the previous range end, range width).
 * Decoding yields a flat, ascending Uint32Array of [start, end] pairs which is
 * probed with a binary search.
 */

/**
 * @param {string} encoded base-36 delta inversion list
 * @returns {Uint32Array} flat [start0, end0, start1, end1, ...]
 */
export function decodeRanges(encoded) {
  if (!encoded) return new Uint32Array(0);
  const parts = encoded.split(',');
  const out = new Uint32Array(parts.length);
  let prev = 0;
  for (let i = 0; i < parts.length; i += 2) {
    const start = prev + parseInt(parts[i], 36);
    const end = start + parseInt(parts[i + 1], 36);
    out[i] = start;
    out[i + 1] = end;
    prev = end;
  }
  return out;
}

/** A lazily decoded, immutable set of code points. */
export class CodepointSet {
  /** @param {string} encoded base-36 delta inversion list */
  constructor(encoded) {
    this._encoded = encoded;
    this._ranges = null;
  }

  get ranges() {
    if (this._ranges === null) {
      this._ranges = decodeRanges(this._encoded);
      this._encoded = null;
    }
    return this._ranges;
  }

  /**
   * @param {number} cp
   * @returns {boolean}
   */
  contains(cp) {
    const r = this.ranges;
    let lo = 0;
    let hi = r.length / 2 - 1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (cp < r[mid * 2]) hi = mid - 1;
      else if (cp > r[mid * 2 + 1]) lo = mid + 1;
      else return true;
    }
    return false;
  }
}

/**
 * Build a first-match-wins lookup over several named sets.
 *
 * @param {Array<[string, string]>} pairs [name, encoded] in priority order
 * @returns {(cp: number) => string|undefined}
 */
export function classifier(pairs) {
  const sets = pairs.map(([name, encoded]) => [name, new CodepointSet(encoded)]);
  return (cp) => {
    for (const [name, set] of sets) {
      if (set.contains(cp)) return name;
    }
    return undefined;
  };
}

