/**
 * The slice of the Unicode Character Database the IDNA algorithms need, with the
 * same call signatures as the `unicodedata` module the reference implementation
 * uses.
 *
 * The tables under ./data/ were generated from UCD 15.0 -- deliberately the same
 * revision as the reference interpreter's `unicodedata`, so that code points
 * assigned only in a later revision report as unassigned here too. That
 * mismatch is observable: it is what makes a Unicode 16.0 letter pass the IDNA
 * code point check and then fail the bidi check.
 */
import { CodepointSet, classifier } from './ranges.mjs';
import * as BIDI from './data/bidi-classes.mjs';
import * as JOIN from './data/joining-types.mjs';
import * as CAT from './data/categories.mjs';
import * as SCRIPT from './data/scripts.mjs';

// Ordered so that the (disjoint) sets are probed cheaply; order is irrelevant
// for correctness because Bidi_Class is a partition.
const bidiClassOf = classifier([
  ['L', BIDI.BC_L],
  ['NSM', BIDI.BC_NSM],
  ['ON', BIDI.BC_ON],
  ['R', BIDI.BC_R],
  ['AL', BIDI.BC_AL],
  ['EN', BIDI.BC_EN],
  ['AN', BIDI.BC_AN],
  ['ES', BIDI.BC_ES],
  ['ET', BIDI.BC_ET],
  ['CS', BIDI.BC_CS],
  ['BN', BIDI.BC_BN],
  ['B', BIDI.BC_B],
  ['WS', BIDI.BC_WS],
]);

const joiningTypeOf = classifier([
  ['T', JOIN.JT_T],
  ['D', JOIN.JT_D],
  ['R', JOIN.JT_R],
  ['L', JOIN.JT_L],
]);

const MARK = new CodepointSet(CAT.MARK);
const VIRAMA = new CodepointSet(CAT.VIRAMA);
const NONPRINTABLE = new CodepointSet(CAT.NONPRINTABLE);

const SCRIPTS = {
