/**
 * Python string primitives that JavaScript spells differently.
 *
 * Python strings are sequences of code points; JavaScript strings are sequences
 * of UTF-16 units. Every place the reference implementation indexes, slices or
 * measures a label, it is doing so in code points, so labels are carried around
 * as code point arrays and only joined back into JS strings at the edges.
 */

/**
 * @param {string} s
 * @returns {number[]} the code points of `s`
 */
export function codepoints(s) {
  const out = [];
  for (const ch of s) out.push(ch.codePointAt(0));
  return out;
}

/**
 * @param {string} s
 * @returns {number} `len(s)` as Python counts it
 */
export function pyLen(s) {
  let n = 0;
  for (const _ of s) n++;
  return n;
}

/**
 * @param {number[]} cps
 * @returns {string}
 */
export function fromCodepoints(cps) {
  let out = '';
  // Chunked to stay clear of the argument-count limit on very long labels.
  for (let i = 0; i < cps.length; i += 4096) {
    out += String.fromCodePoint(...cps.slice(i, i + 4096));
  }
  return out;
}

/**
 * `bytes.lower()` -- ASCII-only case folding, unlike `str.toLowerCase()`.
 *
 * @param {string} s
 * @returns {string}
 */
export function asciiLower(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    out += c >= 0x41 && c <= 0x5a ? String.fromCharCode(c + 0x20) : s[i];
  }
  return out;
}

/**
 * True when every code point of `s` is below U+0080, i.e. `s.encode('ascii')`
 * would succeed.
 *
 * @param {string} s
 * @returns {boolean}
 */
export function isAscii(s) {
  for (let i = 0; i < s.length; i++) {
    if (s.charCodeAt(i) > 0x7f) return false;
  }
  return true;
}

