/**
 * `repr()` and `print()` for the two Python types this program puts on stdout:
 * `str` (inside IDNA error messages) and `bytes` (the encode result).
 */
import { codepoints, isPrintable } from './deps.mjs';

const SHORT_ESCAPES = { 0x09: '\\t', 0x0a: '\\n', 0x0d: '\\r', 0x5c: '\\\\' };

/**
 * Pick the quote character the way CPython's `unicode_repr` does: a single
 * quote, unless the value contains a single quote and no double quote.
 *
 * @param {number[]} cps
 * @returns {string}
 */
function chooseQuote(cps) {
  const hasSingle = cps.includes(0x27);
  const hasDouble = cps.includes(0x22);
  return hasSingle && !hasDouble ? '"' : "'";
}

/**
 * @param {number} cp
 * @returns {string} `\xXX`, `\uXXXX` or `\UXXXXXXXX`, lower-case hex
 */
function hexEscape(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * `repr(s)` for a Python `str`.
 *
 * @param {string} s
 * @returns {string}
 */
export function reprStr(s) {
  const cps = codepoints(s);
  const quote = chooseQuote(cps);
  const quoteCp = quote.charCodeAt(0);
  let out = quote;
  for (const cp of cps) {
    if (cp === quoteCp || cp === 0x5c) out += '\\' + String.fromCodePoint(cp);
    else if (SHORT_ESCAPES[cp] !== undefined) out += SHORT_ESCAPES[cp];
    else if (isPrintable(cp)) out += String.fromCodePoint(cp);
    else out += hexEscape(cp);
  }
  return out + quote;
}

/**
 * `repr(b)` for a Python `bytes`. The value is carried as a JS string whose
 * char codes are the byte values.
 *
 * @param {string} b
 * @returns {string}
 */
export function reprBytes(b) {
  const bytes = [];
  for (let i = 0; i < b.length; i++) bytes.push(b.charCodeAt(i));
  const quote = bytes.includes(0x27) && !bytes.includes(0x22) ? '"' : "'";
  const quoteCp = quote.charCodeAt(0);
  let out = "b" + quote;
  for (const byte of bytes) {
    if (byte === quoteCp || byte === 0x5c) out += '\\' + String.fromCharCode(byte);
    else if (SHORT_ESCAPES[byte] !== undefined) out += SHORT_ESCAPES[byte];
    else if (byte >= 0x20 && byte < 0x7f) out += String.fromCharCode(byte);
    else out += '\\x' + byte.toString(16).padStart(2, '0');
  }
  return out + quote;
}

/**
 * The `U+{:04X}` form used inside IDNA error messages.
 *
 * @param {number} cp
 * @returns {string}
 */
export function unot(cp) {
  return 'U+' + cp.toString(16).toUpperCase().padStart(4, '0');
}

/**
 * `str(x)` as `print()` applies it: bytes get their repr, str is passed
 * through, bools render capitalised.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function pyStr(value) {
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (value && typeof value === 'object' && value.__bytes__ === true) return reprBytes(value.value);
  return String(value);
}

