/**
 * Bootstring / RFC 3492 codec, reimplemented to match CPython's
 * `encodings.punycode` module rather than the textbook algorithm. The
 * differences matter:
 *
 *  - Decoding splits on the LAST hyphen; with no hyphen at all the whole string
 *    is treated as extended data and the literal part is empty. So a label like
 *    `abc` decodes to U+0082 U+0081 U+0080 instead of being rejected.
 *  - The extended part is upper-cased before digit lookup, so mixed case works.
 *  - There is no overflow guard on the accumulated delta; the only bound is the
 *    resulting code point exceeding U+10FFFF.
 *  - Decoded code points are not checked against the surrogate range.
 *
 * Parameters are the fixed RFC 3492 ones: base 36, tmin 1, tmax 26, skew 38,
 * damp 700, initial bias 72, initial n 0x80.
 */
import { codepoints, fromCodepoints } from '../pycompat/strings.mjs';

const BASE = 36;
const TMIN = 1;
const TMAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 0x80;
const DIGITS = 'abcdefghijklmnopqrstuvwxyz0123456789';

/** Raised for the same inputs that make CPython's codec raise `UnicodeError`. */
export class BootstringError extends Error {}

/** Integer division that truncates toward zero for non-negative operands. */
const idiv = (a, b) => Math.floor(a / b);

/**
 * Threshold for digit position `j`, clamped to [tmin, tmax].
 *
 * @param {number} j
 * @param {number} bias
 * @returns {number}
 */
function threshold(j, bias) {
  const res = BASE * (j + 1) - bias;
  if (res < TMIN) return TMIN;
  if (res > TMAX) return TMAX;
  return res;
}

/**
 * @param {number} delta
 * @param {boolean} first
 * @param {number} numchars
 * @returns {number}
 */
function adapt(delta, first, numchars) {
  let d = first ? idiv(delta, DAMP) : idiv(delta, 2);
  d += idiv(d, numchars);
  let divisions = 0;
  while (d > 455) {
    d = idiv(d, BASE - TMIN);
    divisions += BASE;
  }
  return divisions + idiv(BASE * d, d + SKEW);
}

// ---------------------------------------------------------------- encoding --

/**
 * Split the input into its basic (< U+0080) code points and the sorted, unique
 * set of non-basic ones.
 *
 * @param {number[]} cps
 * @returns {{ basic: number[], extended: number[] }}
 */
function segregate(cps) {
  const basic = [];
  const extended = new Set();
  for (const cp of cps) {
    if (cp < 0x80) basic.push(cp);
    else extended.add(cp);
  }
  return { basic, extended: [...extended].sort((a, b) => a - b) };
}

/**
 * Count the code points of `cps` strictly below `max`.
 *
 * @param {number[]} cps
 * @param {number} max
 * @returns {number}
 */
function selectiveLen(cps, max) {
  let res = 0;
  for (const cp of cps) if (cp < max) res++;
  return res;
}

/**
 * Locate the next occurrence of `target` after `pos`, tracking the index the
 * character would have if only code points <= target existed.
 *
 * @returns {[number, number]} [index, pos], or [-1, -1] when exhausted
 */
function selectiveFind(cps, target, index, pos) {
  const len = cps.length;
  for (;;) {
    pos += 1;
    if (pos === len) return [-1, -1];
    const cp = cps[pos];
    if (cp === target) return [index + 1, pos];
    if (cp < target) index += 1;
  }
}

/**
 * RFC 3492 section 3.2, expressed as CPython's insertion-unsort.
 *
 * @param {number[]} cps
 * @param {number[]} extended
 * @returns {number[]} the delta sequence
 */
function insertionUnsort(cps, extended) {
  let oldchar = INITIAL_N;
  let oldindex = -1;
  const result = [];
  for (const char of extended) {
    let index = -1;
    let pos = -1;
    const curlen = selectiveLen(cps, char);
    let delta = (curlen + 1) * (char - oldchar);
    for (;;) {
      [index, pos] = selectiveFind(cps, char, index, pos);
      if (index === -1) break;
      delta += index - oldindex;
      result.push(delta - 1);
      oldindex = index;
      delta = 0;
    }
    oldchar = char;
  }
  return result;
}

/**
 * @param {number} n
 * @param {number} bias
 * @returns {string}
 */
function generateGeneralizedInteger(n, bias) {
  let out = '';
  let j = 0;
  let value = n;
  for (;;) {
    const t = threshold(j, bias);
    if (value < t) return out + DIGITS[value];
    out += DIGITS[t + ((value - t) % (BASE - t))];
    value = idiv(value - t, BASE - t);
    j += 1;
  }
}

/**
 * @param {number} baselen
 * @param {number[]} deltas
 * @returns {string}
 */
function generateIntegers(baselen, deltas) {
  let out = '';
  let bias = INITIAL_BIAS;
  for (let points = 0; points < deltas.length; points++) {
    const delta = deltas[points];
    out += generateGeneralizedInteger(delta, bias);
    bias = adapt(delta, points === 0, baselen + points + 1);
  }
  return out;
}

/**
 * `str.encode('punycode')`.
 *
 * @param {string} text
 * @returns {string} ASCII bytes, one per JS char
 */
export function bootstringEncode(text) {
  const cps = codepoints(text);
  const { basic, extended } = segregate(cps);
  const deltas = insertionUnsort(cps, extended);
  const tail = generateIntegers(basic.length, deltas);
  const head = basic.map((cp) => String.fromCharCode(cp)).join('');
  return head ? head + '-' + tail : tail;
}

// ---------------------------------------------------------------- decoding --

/**
 * @param {string} extended upper-cased extended part
 * @param {number} extpos
 * @param {number} bias
 * @returns {[number, number]} [next position, decoded delta]
 */
function decodeGeneralizedNumber(extended, extpos, bias) {
  let result = 0;
  let w = 1;
  let j = 0;
  for (;;) {
    if (extpos >= extended.length) throw new BootstringError('incomplete punicode string');
    const char = extended.charCodeAt(extpos);
    extpos += 1;
    let digit;
    if (char >= 0x41 && char <= 0x5a) digit = char - 0x41;
    else if (char >= 0x30 && char <= 0x39) digit = char - 22;
    else throw new BootstringError(`Invalid extended code point '${extended[extpos - 1]}'`);
    const t = threshold(j, bias);
    result += digit * w;
    if (digit < t) return [extpos, result];
    w = w * (BASE - t);
    j += 1;
  }
}

/**
 * RFC 3492 section 3.2 decoding, as CPython's `insertion_sort`.
 *
 * @param {number[]} base literal code points
 * @param {string} extended upper-cased extended part
 * @returns {number[]}
 */
function insertionSort(base, extended) {
  let out = base.slice();
  let char = INITIAL_N;
  let pos = -1;
  let bias = INITIAL_BIAS;
  let extpos = 0;
  while (extpos < extended.length) {
    const [newpos, delta] = decodeGeneralizedNumber(extended, extpos, bias);
    pos += delta + 1;
    char += idiv(pos, out.length + 1);
    if (char > 0x10ffff) throw new BootstringError(`Invalid character U+${char.toString(16)}`);
    pos = pos % (out.length + 1);
    out.splice(pos, 0, char);
    bias = adapt(delta, extpos === 0, out.length);
    extpos = newpos;
  }
  return out;
}

/**
 * `bytes.decode('punycode')`.
 *
 * @param {string} text ASCII bytes, one per JS char
 * @returns {string}
 */
export function bootstringDecode(text) {
  const pos = text.lastIndexOf('-');
  let base;
  let extended;
  if (pos === -1) {
    base = [];
    extended = asciiUpper(text);
  } else {
    base = codepoints(text.slice(0, pos));
    extended = asciiUpper(text.slice(pos + 1));
  }
  return fromCodepoints(insertionSort(base, extended));
}

/**
 * `str.upper()` restricted to the ASCII range the extended part can hold.
 *
 * @param {string} s
 * @returns {string}
 */
function asciiUpper(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    out += c >= 0x61 && c <= 0x7a ? String.fromCharCode(c - 0x20) : s[i];
  }
  return out;
}

