}

// ---------------------------------------------------------------- decoding --

/**
 * @param {string} extended upper-cased extended part
 * @param {number} extpos
 * @param {number} bias
 * @returns {[number, number]} [next position, decoded delta]
 */
function decodeGeneralizedNumber(extended, extpos, bias) {
  let result = 0;
  let w = 1;
  let j = 0;
  for (;;) {
    if (extpos >= extended.length) throw new BootstringError('incomplete punicode string');
    const char = extended.charCodeAt(extpos);
    extpos += 1;
    let digit;
    if (char >= 0x41 && char <= 0x5a) digit = char - 0x41;
    else if (char >= 0x30 && char <= 0x39) digit = char - 22;
    else throw new BootstringError(`Invalid extended code point '${extended[extpos - 1]}'`);
    const t = threshold(j, bias);
    result += digit * w;
    if (digit < t) return [extpos, result];
    w = w * (BASE - t);
    j += 1;
  }
}

/**
 * RFC 3492 section 3.2 decoding, as CPython's `insertion_sort`.
 *
 * @param {number[]} base literal code points
 * @param {string} extended upper-cased extended part
 * @returns {number[]}
 */
function insertionSort(base, extended) {
  let out = base.slice();
  let char = INITIAL_N;
  let pos = -1;
  let bias = INITIAL_BIAS;
  let extpos = 0;
