/**
 * The IDNA exception hierarchy.
 *
 * The shape matters, not just the messages: in the reference implementation
 * `IDNAError` derives from `UnicodeError`, which derives from `ValueError`. A
 * CONTEXTJ failure is raised inside a `try` whose handler catches `ValueError`,
 * so the specific `InvalidCodepointContext` never escapes -- it is swallowed and
 * re-reported as "Unknown codepoint adjacent to joiner ...". `isValueError` is
 * what reproduces that.
 */

/** Base of everything this module raises; stands in for `ValueError`. */
export class ValueError extends Error {}

/** `idna.IDNAError` -- the only class the calling script catches by name. */
export class IDNAError extends ValueError {
  constructor(message) {
    super(message);
    this.name = 'IDNAError';
  }
}

/** `idna.IDNABidiError` */
export class IDNABidiError extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'IDNABidiError';
  }
}

/** `idna.InvalidCodepoint` */
export class InvalidCodepoint extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'InvalidCodepoint';
  }
}

/** `idna.InvalidCodepointContext` */
export class InvalidCodepointContext extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'InvalidCodepointContext';
  }
}

/**
 * True for anything `except ValueError:` would catch -- which includes every
 * `IDNAError`.
 *
 * @param {unknown} err
 * @returns {boolean}
 */
export function isValueError(err) {
  return err instanceof ValueError;
}

/**
 * True for anything `except idna.core.IDNAError:` would catch.
 *
 * @param {unknown} err
 * @returns {boolean}
 */
export function isIDNAError(err) {
  return err instanceof IDNAError;
}

