/**
 * Label validity rules: RFC 5892 (code point classes and the contextual rules)
 * and RFC 5893 (bidi).
 */
import { codepoints, fromCodepoints, pyLen } from '../pycompat/strings.mjs';
import { reprStr, unot } from '../pycompat/repr.mjs';
import { bidirectional, isMark, isScript, isVirama, joiningType } from '../unicode/ucd.mjs';
import { CodepointSet } from '../unicode/ranges.mjs';
import * as CLASSES from '../unicode/data/idna-classes.mjs';
import { IDNABidiError, IDNAError, InvalidCodepoint, InvalidCodepointContext, isValueError } from './errors.mjs';

const PVALID = new CodepointSet(CLASSES.PVALID);
const CONTEXTJ = new CodepointSet(CLASSES.CONTEXTJ);
const CONTEXTO = new CodepointSet(CLASSES.CONTEXTO);

/**
 * A label is at most 63 octets.
 *
 * Note the reference implementation applies `len()` to whatever it is handed:
 * octets for an already-encoded label, but *code points* when a caller passes a
 * `str`. Both call sites are reproduced faithfully -- see `valid_label_length`
 * in ../idna/index.mjs.
 *
 * @param {number} length
 * @returns {boolean}
 */
export function lengthWithin(length, limit) {
  return length <= limit;
}

/**
 * @param {string} label
 * @throws {IDNAError} when the label is not in Normalization Form C
 */
export function checkNfc(label) {
  if (label.normalize('NFC') !== label) {
    throw new IDNAError('Label must be in Normalization Form C');
  }
}

/**
 * @param {number[]} cps
 * @returns {true}
 * @throws {IDNAError}
 */
export function checkHyphenOk(cps) {
  const HYPHEN = 0x2d;
  if (cps.length >= 4 && cps[2] === HYPHEN && cps[3] === HYPHEN) {
    throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position');
  }
  if (cps[0] === HYPHEN || cps[cps.length - 1] === HYPHEN) {
    throw new IDNAError('Label must not start or end with a hyphen');
  }
  return true;
}

/**
 * @param {number[]} cps
 * @throws {IDNAError}
 */
export function checkInitialCombiner(cps) {
  if (isMark(cps[0])) {
    throw new IDNAError('Label begins with an illegal combining character');
  }
}

/**
 * RFC 5892 Appendix A.1/A.2 -- the ZWNJ and ZWJ rules.
 *
 * @param {number[]} cps
 * @param {number} pos
 * @returns {boolean}
 */
export function validContextJ(cps, pos) {
  const cp = cps[pos];

  if (cp === 0x200c) {
    if (pos > 0 && isVirama(cps[pos - 1])) return true;

    let ok = false;
    for (let i = pos - 1; i >= 0; i--) {
      const jt = joiningType(cps[i]);
      if (jt === 'T') continue;
      if (jt === 'L' || jt === 'D') { ok = true; break; }
      break;
    }
    if (!ok) return false;

    ok = false;
    for (let i = pos + 1; i < cps.length; i++) {
      const jt = joiningType(cps[i]);
      if (jt === 'T') continue;
      if (jt === 'R' || jt === 'D') { ok = true; break; }
      break;
    }
    return ok;
  }

  if (cp === 0x200d) {
    return pos > 0 && isVirama(cps[pos - 1]);
  }

  return false;
}

/**
 * RFC 5892 Appendix A.3 - A.9 -- the CONTEXTO rules.
 *
 * @param {number[]} cps
 * @param {number} pos
 * @returns {boolean}
 */
export function validContextO(cps, pos) {
  const cp = cps[pos];
  const len = cps.length;

  // MIDDLE DOT: only between two U+006C.
  if (cp === 0x00b7) {
    if (pos > 0 && pos < len - 1) {
      return cps[pos - 1] === 0x006c && cps[pos + 1] === 0x006c;
    }
    return false;
  }

  // GREEK LOWER NUMERAL SIGN: must be followed by a Greek code point.
  if (cp === 0x0375) {
    if (pos < len - 1 && len > 1) return isScript(cps[pos + 1], 'Greek');
    return false;
  }

  // HEBREW PUNCTUATION GERESH / GERSHAYIM: must follow a Hebrew code point.
  if (cp === 0x05f3 || cp === 0x05f4) {
    if (pos > 0) return isScript(cps[pos - 1], 'Hebrew');
    return false;
  }

  // KATAKANA MIDDLE DOT: the label must contain Hiragana, Katakana or Han.
  if (cp === 0x30fb) {
    for (const other of cps) {
      if (other === 0x30fb) continue;
      if (isScript(other, 'Hiragana') || isScript(other, 'Katakana') || isScript(other, 'Han')) return true;
    }
    return false;
  }

  // The two families of Arabic-Indic digits must not be mixed.
  if (cp >= 0x0660 && cp <= 0x0669) {
    for (const other of cps) if (other >= 0x06f0 && other <= 0x06f9) return false;
    return true;
  }
  if (cp >= 0x06f0 && cp <= 0x06f9) {
    for (const other of cps) if (other >= 0x0660 && other <= 0x0669) return false;
    return true;
  }

  return false;
}

const RTL_ALLOWED = new Set(['R', 'AL', 'AN', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']);
const LTR_ALLOWED = new Set(['L', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']);

/**
 * RFC 5893 -- the Bidi Rule. Only applied to labels that actually contain
 * right-to-left code points, unless `checkLtr` forces it.
 *
 * @param {number[]} cps
 * @param {boolean} [checkLtr]
 * @returns {true}
 * @throws {IDNABidiError}
 */
export function checkBidi(cps, checkLtr = false) {
  let bidiLabel = false;
  for (let idx = 0; idx < cps.length; idx++) {
    const direction = bidirectional(cps[idx]);
    if (direction === '') {
      // The code point is unassigned in this UCD revision -- it comes from a
      // newer version of Unicode than the character database.
      throw new IDNABidiError(
        `Unknown directionality in label ${reprStr(fromCodepoints(cps))} at position ${idx + 1}`
      );
    }
    if (direction === 'R' || direction === 'AL' || direction === 'AN') bidiLabel = true;
  }
  if (!bidiLabel && !checkLtr) return true;

  // Bidi rule 1
  let rtl;
  const first = bidirectional(cps[0]);
  if (first === 'R' || first === 'AL') rtl = true;
  else if (first === 'L') rtl = false;
  else {
    throw new IDNABidiError(
      `First codepoint in label ${reprStr(fromCodepoints(cps))} must be directionality L, R or AL`
    );
  }

  let validEnding = false;
  let numberType = null;
  for (let idx = 0; idx < cps.length; idx++) {
    const direction = bidirectional(cps[idx]);
    if (rtl) {
      // Bidi rule 2
      if (!RTL_ALLOWED.has(direction)) {
        throw new IDNABidiError(
          `Invalid direction for codepoint at position ${idx + 1} in a right-to-left label`
        );
      }
      // Bidi rule 3
      if (direction === 'R' || direction === 'AL' || direction === 'EN' || direction === 'AN') validEnding = true;
      else if (direction !== 'NSM') validEnding = false;
      // Bidi rule 4
      if (direction === 'AN' || direction === 'EN') {
        if (!numberType) numberType = direction;
        else if (numberType !== direction) {
          throw new IDNABidiError('Can not mix numeral types in a right-to-left label');
        }
      }
    } else {
      // Bidi rule 5
      if (!LTR_ALLOWED.has(direction)) {
        throw new IDNABidiError(
          `Invalid direction for codepoint at position ${idx + 1} in a left-to-right label`
        );
      }
      // Bidi rule 6
      if (direction === 'L' || direction === 'EN') validEnding = true;
      else if (direction !== 'NSM') validEnding = false;
    }
  }

  if (!validEnding) throw new IDNABidiError('Label ends with illegal codepoint directionalities');

  return true;
}

/**
 * Full label validation.
 *
 * @param {string} label a Python `str`; byte inputs are decoded by the caller
 * @throws {IDNAError}
 */
export function checkLabel(label) {
  const cps = codepoints(label);
  if (cps.length === 0) throw new IDNAError('Empty Label');

  checkNfc(label);
  checkHyphenOk(cps);
  checkInitialCombiner(cps);

  for (let pos = 0; pos < cps.length; pos++) {
    const cp = cps[pos];
    if (PVALID.contains(cp)) continue;
    if (CONTEXTJ.contains(cp)) {
      // The reference implementation wraps this in `except ValueError`, and
      // InvalidCodepointContext *is* a ValueError -- so every CONTEXTJ failure,
      // however it arises, surfaces as this one message.
      try {
        if (!validContextJ(cps, pos)) {
          throw new InvalidCodepointContext(
            `Joiner ${unot(cp)} not allowed at position ${pos + 1} in ${reprStr(label)}`
          );
        }
      } catch (err) {
        if (!isValueError(err)) throw err;
        throw new IDNAError(
          `Unknown codepoint adjacent to joiner ${unot(cp)} at position ${pos + 1} in ${reprStr(label)}`
        );
      }
    } else if (CONTEXTO.contains(cp)) {
      if (!validContextO(cps, pos)) {
        throw new InvalidCodepointContext(
          `Codepoint ${unot(cp)} not allowed at position ${pos + 1} in ${reprStr(label)}`
        );
      }
    } else {
      throw new InvalidCodepoint(
        `Codepoint ${unot(cp)} at position ${pos + 1} of ${reprStr(label)} not allowed`
      );
    }
  }

  checkBidi(cps);
}

