/**
 * A-label <-> U-label conversion for a single label.
 *
 * Byte strings are modelled as JavaScript strings whose char codes are the byte
 * values; every value that reaches here is ASCII, so length in chars equals
 * length in octets.
 */
import { asciiLower, isAscii } from '../pycompat/strings.mjs';
import { bootstringDecode, bootstringEncode } from './bootstring.mjs';
import { checkLabel } from './checks.mjs';
import { IDNAError } from './errors.mjs';
import { validLabelLength } from './lengths.mjs';

const ALABEL_PREFIX = 'xn--';

/**
 * Convert one label to its A-label form.
 *
 * An all-ASCII label is validated but returned *verbatim*, which is why case is
 * preserved: `alabel('UPPER')` is `b'UPPER'` even though validation lower-cases
 * the label first.
 *
 * @param {string} label
 * @returns {string} ASCII octets
 * @throws {IDNAError}
 */
export function alabel(label) {
  if (isAscii(label)) {
    ulabel(label);
    if (!validLabelLength(label)) throw new IDNAError('Label too long');
    return label;
  }

  checkLabel(label);
  const labelBytes = ALABEL_PREFIX + bootstringEncode(label);
  if (!validLabelLength(labelBytes)) throw new IDNAError('Label too long');
  return labelBytes;
}

/**
 * Convert one label to its U-label form.
 *
 * @param {string} label either a Unicode label or ASCII octets
 * @returns {string}
 * @throws {IDNAError}
 */
export function ulabel(label) {
  if (!isAscii(label)) {
    checkLabel(label);
    return label;
  }

  let labelBytes = asciiLower(label);
  if (labelBytes.startsWith(ALABEL_PREFIX)) {
    labelBytes = labelBytes.slice(ALABEL_PREFIX.length);
    if (!labelBytes) {
      throw new IDNAError('Malformed A-label, no Punycode eligible content found');
    }
    if (labelBytes[labelBytes.length - 1] === '-') {
      throw new IDNAError('A-label must not end with a hyphen');
    }
  } else {
    checkLabel(labelBytes);
    return labelBytes;
  }

  let decoded;
  try {
    decoded = bootstringDecode(labelBytes);
  } catch {
    throw new IDNAError('Invalid A-label');
  }
  checkLabel(decoded);
  return decoded;
}

