/**
 * The DNS length limits.
 *
 * `valid_label_length` is deliberately polymorphic in the reference
 * implementation: it applies `len()` to whatever it is given. Internal callers
 * hand it octets, but a caller passing a `str` gets a *code point* count. Both
 * agree for ASCII, and using a code point count covers both cases exactly.
 */
import { pyLen } from '../pycompat/strings.mjs';

/**
 * @param {string} label octets, or a Unicode label
 * @returns {boolean} false when the label exceeds 63
 */
export function validLabelLength(label) {
  return pyLen(label) <= 63;
}

/**
 * @param {string} domain octets of the full, dot-joined domain
 * @param {boolean} trailingDot
 * @returns {boolean} false when the domain exceeds 253 (254 with a trailing dot)
 */
export function validStringLength(domain, trailingDot) {
  return domain.length <= (trailingDot ? 254 : 253);
}

