/**
 * The label separators recognised in non-strict mode: FULL STOP, IDEOGRAPHIC
 * FULL STOP, FULLWIDTH FULL STOP and HALFWIDTH IDEOGRAPHIC FULL STOP.
 */
const UNICODE_DOTS = /[.。．｡]/;

/**
 * Transitional processing was removed from UTS #46; the reference
 * implementation now warns when the argument is set. The flag has no effect
 * unless UTS #46 remapping is also requested, which this program never does.
 */
function warnTransitional(transitional) {
  if (transitional) {
    process.emitWarning(
      'Transitional processing has been removed from UTS #46. The transitional argument will be removed in a future version.',
      'DeprecationWarning'
    );
  }
}

/**
 * @param {string} s
 * @param {{strict?: boolean, transitional?: boolean}} [options]
 * @returns {string} the encoded domain as ASCII octets
 * @throws {IDNAError}
 */
export function encode(s, options = {}) {
  const { strict = false, transitional = false } = options;
  warnTransitional(transitional);

  const labels = strict ? s.split('.') : s.split(UNICODE_DOTS);
  if (labels.length === 0 || (labels.length === 1 && labels[0] === '')) {
    throw new IDNAError('Empty domain');
  }

  let trailingDot = false;
  if (labels[labels.length - 1] === '') {
    labels.pop();
    trailingDot = true;
  }

  const result = [];
  for (const label of labels) {
    const encoded = alabel(label);
    if (encoded) result.push(encoded);
    else throw new IDNAError('Empty label');
  }
  if (trailingDot) result.push('');

  const joined = result.join('.');
  if (!validStringLength(joined, trailingDot)) throw new IDNAError('Domain too long');
  return joined;
}

