/**
 * The slice of Python's `argparse` this program relies on.
 *
 * Faithfulness here is about more than option names: the reference behaviour
 * includes long-option abbreviation, `--opt=value`, the rules that decide
 * whether a token starting with '-' is an option or a value (negative numbers
 * and anything containing a space are values), the precedence of the
 * "required arguments" error over "unrecognized arguments", exit status 2, and
 * the exact line wrapping of the usage message.
 */
import { basename } from 'node:path';
import { reprStr } from './repr.mjs';

/** Thrown to unwind to the top-level handler, which exits the process. */
export class ArgumentParserExit extends Error {
  /**
   * @param {number} status
   * @param {string} [stdout]
   * @param {string} [stderr]
   */
  constructor(status, stdout = '', stderr = '') {
    super(`argument parser exited with status ${status}`);
    this.status = status;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/**
 * `shutil.get_terminal_size().columns`: the COLUMNS environment variable wins,
 * then the real terminal width, then 80.
 *
 * @returns {number}
 */
function terminalColumns() {
  const env = process.env.COLUMNS;
  if (env) {
    const n = Number.parseInt(env, 10);
    if (Number.isInteger(n) && n > 0) return n;
  }
  return process.stdout.columns || 80;
}

export class ArgumentParser {
  /** @param {{prog?: string}} [options] */
  constructor(options = {}) {
    this.prog = options.prog ?? basename(process.argv[1] ?? 'prog');
    /** @type {Array<object>} */
    this.actions = [];
    this.addArgument('-h', '--help', { action: 'help', help: 'show this help message and exit' });
  }

  /**
   * @param {...(string|object)} args option strings followed by an options object
   */
  addArgument(...args) {
    const spec = typeof args[args.length - 1] === 'object' ? args.pop() : {};
    const optionStrings = /** @type {string[]} */ (args);
    const longest = optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0];
    const dest = spec.dest ?? longest.replace(/^--?/, '').replace(/-/g, '_');
    const action = {
      optionStrings,
      dest,
      required: spec.required ?? false,
      choices: spec.choices ?? null,
      type: spec.type ?? ((v) => v),
      default: spec.default ?? null,
      help: spec.help ?? null,
      isHelp: spec.action === 'help',
      metavar: spec.metavar ?? (spec.choices ? `{${spec.choices.join(',')}}` : dest.toUpperCase()),
    };
    this.actions.push(action);
    return action;
  }

  // ------------------------------------------------------------ formatting --

  /** @returns {number} the text width the formatter wraps to */
  get _width() {
    return terminalColumns() - 2;
  }

  /**
   * How an action appears inside the usage line.
   *
   * @param {object} action
   * @returns {string}
   */
  _usagePart(action) {
    const body = action.isHelp
      ? action.optionStrings[0]
      : `${action.optionStrings[action.optionStrings.length - 1]} ${action.metavar}`;
    return action.required ? body : `[${body}]`;
  }

  /**
   * Reproduces `HelpFormatter._format_usage`, including its wrapping rules.
   *
   * @returns {string} ends with a single newline
   */
  formatUsage() {
    const prefix = 'usage: ';
    const textWidth = this._width;
    const parts = this.actions.map((a) => this._usagePart(a));
    const oneLine = [this.prog, parts.join(' ')].filter(Boolean).join(' ');

    if (prefix.length + oneLine.length <= textWidth) return `${prefix}${oneLine}\n`;

    // Wrap: keep the program name on the first line when it is short enough,
    // and align continuation lines under it.
    const getLines = (items, indent, withPrefix) => {
      const lines = [];
      let line = [];
      let lineLen = (withPrefix ? prefix.length : indent.length) - 1;
      for (const part of items) {
        if (lineLen + 1 + part.length > textWidth && line.length) {
          lines.push(indent + line.join(' '));
          line = [];
          lineLen = indent.length - 1;
        }
        line.push(part);
        lineLen += 1 + part.length;
      }
      if (line.length) lines.push(indent + line.join(' '));
      if (withPrefix) lines[0] = lines[0].slice(indent.length);
      return lines;
    };

    let lines;
    if (prefix.length + this.prog.length <= 0.75 * textWidth) {
      const indent = ' '.repeat(prefix.length + this.prog.length + 1);
      lines = getLines([this.prog, ...parts], indent, true);
    } else {
      const indent = ' '.repeat(prefix.length);
      lines = [this.prog, ...getLines(parts, indent, false)];
    }
    return `${prefix}${lines.join('\n')}\n`;
  }

  /**
   * Reproduces `ArgumentParser.format_help` for a parser with no positionals,
   * no description and no epilog.
   *
   * @returns {string}
   */
  formatHelp() {
    const indent = 2;
    const maxHelpPosition = 24;
    const invocation = (a) =>
      a.isHelp
        ? a.optionStrings.join(', ')
        : a.optionStrings.map((s) => `${s} ${a.metavar}`).join(', ');

    const actionMaxLength = Math.max(...this.actions.map((a) => invocation(a).length + indent));
    const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);
    const helpWidth = Math.max(this._width - helpPosition, 11);

    let out = this.formatUsage().replace(/\n$/, '\n\n');
    out += 'options:\n';
    for (const action of this.actions) {
      const head = ' '.repeat(indent) + invocation(action);
      if (!action.help) {
        out += `${head}\n`;
        continue;
      }
      const words = action.help.split(/\s+/).filter(Boolean);
      const wrapped = [];
      let line = '';
      for (const word of words) {
        if (line && line.length + 1 + word.length > helpWidth) {
          wrapped.push(line);
          line = word;
        } else line = line ? `${line} ${word}` : word;
      }
      if (line) wrapped.push(line);
      if (head.length <= helpPosition - 2) {
        out += head + ' '.repeat(helpPosition - head.length) + wrapped[0] + '\n';
      } else {
        out += `${head}\n${' '.repeat(helpPosition)}${wrapped[0]}\n`;
      }
      for (const extra of wrapped.slice(1)) out += ' '.repeat(helpPosition) + extra + '\n';
    }
    return out.replace(/\n+$/, '\n');
  }

  // ---------------------------------------------------------------- errors --

  /**
   * @param {string} message
   * @throws {ArgumentParserExit} always
   */
  error(message) {
    throw new ArgumentParserExit(2, '', `${this.formatUsage()}${this.prog}: error: ${message}\n`);
  }

  // --------------------------------------------------------------- parsing --

  /**
   * `_parse_optional`: decide whether a token introduces an option.
   *
   * @param {string} token
   * @returns {{action: object|null, explicitValue: string|null}|null} null means
   *   the token is a plain value
   */
  _classify(token) {
    if (!token) return null;
    if (!token.startsWith('-')) return null;

    const exact = this.actions.find((a) => a.optionStrings.includes(token));
    if (exact) return { action: exact, explicitValue: null };

    if (token.length === 1) return null; // a bare '-' is a value

    if (token.includes('=')) {
      const [name, ...rest] = token.split('=');
      const byName = this.actions.find((a) => a.optionStrings.includes(name));
      if (byName) return { action: byName, explicitValue: rest.join('=') };
    }

    const matched = this._matchAbbreviation(token);
    if (matched) return matched;

    // A negative number is a value, since no option looks like one.
    if (NEGATIVE_NUMBER.test(token)) return null;
    if (token.includes(' ')) return null;

    return { action: null, explicitValue: null }; // an unknown option
  }

  /**
   * `_get_option_tuples`: resolve a unique long-option abbreviation.
   *
   * @param {string} token
   * @returns {{action: object, explicitValue: string|null}|null}
   */
  _matchAbbreviation(token) {
    if (!token.startsWith('--')) return null;
    const eq = token.indexOf('=');
    const prefix = eq === -1 ? token : token.slice(0, eq);
    const explicitValue = eq === -1 ? null : token.slice(eq + 1);

    const hits = [];
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        if (optionString.startsWith(prefix)) hits.push([action, optionString]);
      }
    }
    if (hits.length === 1) return { action: hits[0][0], explicitValue };
    if (hits.length > 1) {
      const names = hits.map(([, s]) => s).join(', ');
      this.error(`ambiguous option: ${token} could match ${names}`);
    }
    return null;
  }

  /**
   * @param {string[]} argv
   * @returns {Record<string, unknown>}
   * @throws {ArgumentParserExit}
   */
  parseArgs(argv = process.argv.slice(2)) {
    /** @type {Record<string, unknown>} */
    const namespace = {};
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = action.default;
    }

    const seen = new Set();
    const extras = [];
    let onlyValues = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (!onlyValues && token === '--') {
        // Everything after the first '--' is a value; with no positionals
        // declared, the separator itself is left over too.
        onlyValues = true;
        extras.push(token);
        continue;
      }

      const classified = onlyValues ? null : this._classify(token);
      if (classified === null) {
        extras.push(token);
        continue;
      }

      const { action, explicitValue } = classified;
      if (action === null) {
        extras.push(token);
        continue;
      }

      if (action.isHelp) {
        throw new ArgumentParserExit(0, this.formatHelp(), '');
      }

      let raw = explicitValue;
      if (raw === null) {
        const next = i + 1 < argv.length ? argv[i + 1] : undefined;
        if (next === undefined || this._classify(next) !== null) {
          this.error(`argument ${action.optionStrings.join('/')}: expected one argument`);
        }
        raw = next;
        i += 1;
      }

      const value = action.type(raw);
      if (action.choices && !action.choices.includes(value)) {
        const choices = action.choices.map((c) => reprStr(c)).join(', ');
        this.error(
          `argument ${action.optionStrings.join('/')}: invalid choice: ${reprStr(String(value))} (choose from ${choices})`
        );
      }
      namespace[action.dest] = value;
      seen.add(action);
    }

    const missing = this.actions.filter((a) => a.required && !seen.has(a));
    if (missing.length) {
      const names = missing.map((a) => a.optionStrings.join('/')).join(', ');
      this.error(`the following arguments are required: ${names}`);
    }

    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

/**
 * Python's `bool` applied to a command-line string: every non-empty string is
 * true, including 'False' and '0'.
 *
 * @param {string} value
 * @returns {boolean}
 */
export function pyBool(value) {
  return value.length > 0;
}

