/**
 * Port of dataset/idna/test8.py.
 *
 * Reads --domain / --mode / --transitional / --strict, then runs the IDNA
 * encode and/or decode paths and prints the same four possible lines the
 * original does, in the same order.
 *
 * Run: node test8.mjs --domain example.com --mode both
 */
import { ArgumentParser, ArgumentParserExit, pyBool } from './lib/pycompat/argparse.mjs';
import { pyStr, reprBytes } from './lib/pycompat/repr.mjs';
import * as idna from './lib/idna/index.mjs';
import { TRANSITIONAL_DEPRECATION } from './lib/idna/index.mjs';

/** `print(...)`: one value, then a newline, on stdout. */
const print = (value) => process.stdout.write(pyStr(value) + '\n');

/**
 * Reproduces the `DeprecationWarning` the reference implementation raises with
 * `stacklevel=2`, which attributes the warning to the call site in the script.
 * Python's default warning filter shows each location once.
 *
 * @param {number} line
 * @param {string} source
 * @returns {() => void}
 */
const shown = new Set();
function transitionalWarner(line, source) {
  return () => {
    if (shown.has(line)) return;
    shown.add(line);
    process.stderr.write(`test8.py:${line}: DeprecationWarning: ${TRANSITIONAL_DEPRECATION}\n  ${source}\n`);
  };
}

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--domain', { type: String, required: true });
  parser.addArgument('--mode', { type: String, required: true, choices: ['encode', 'decode', 'both'] });
  parser.addArgument('--transitional', { type: pyBool, required: false, default: false });
  parser.addArgument('--strict', { type: pyBool, required: false, default: false });
  const args = parser.parseArgs();

  const domain = /** @type {string} */ (args.domain);
  const mode = /** @type {string} */ (args.mode);
  const transitional = /** @type {boolean} */ (args.transitional);
  const strict = /** @type {boolean} */ (args.strict);

  const firstLabel = domain.split('.')[0];

  if (mode === 'encode' || mode === 'both') {
    // Encode
    let encoded = null;
    try {
      encoded = idna.encode(domain, {
        transitional,
        strict,
        warn: transitionalWarner(21, 'encoded = idna.encode(domain, transitional=transitional, strict=strict)'),
      });
      print(reprBytes(encoded));
    } catch (err) {
      if (!idna.isIDNAError(err)) throw err;
      print(`encode_error: ${err.message}`);
      encoded = null;
    }

    // Fetch the U-label of the first label
    if (firstLabel && encoded) {
      try {
        const ulabel = idna.ulabel(
          idna.encode(firstLabel, {
            transitional,
            strict,
            warn: transitionalWarner(
              30,
              'ulabel = idna.ulabel(idna.encode(first_label, transitional=transitional, strict=strict))'
            ),
          })
        );
        print(ulabel);
      } catch {
        // bare `except: pass`
      }
    }
  }

  if (mode === 'decode' || mode === 'both') {
    // Decode (in case the input is already encoded)
    try {
      print(idna.decode(domain, { strict }));
    } catch (err) {
      if (!idna.isIDNAError(err)) throw err;
      print(`decode_error: ${err.message}`);
    }
  }

  // Always check the validity of the processed label
  if (firstLabel) {
    try {
      print(idna.validLabelLength(firstLabel));
    } catch {
      // bare `except: pass`
    }
  }
}

try {
  main();
} catch (err) {
  if (err instanceof ArgumentParserExit) {
    if (err.stdout) process.stdout.write(err.stdout);
    if (err.stderr) process.stderr.write(err.stderr);
    process.exit(err.status);
  }
  throw err;
}

