/**
 * Public surface of the IDNA library: `encode`, `decode`, the single-label
 * helpers, and the `core` namespace the caller reaches into for the exception
 * type.
 */
import { alabel, ulabel } from './codec.mjs';
import { checkBidi, checkHyphenOk, checkInitialCombiner, checkLabel, checkNfc, validContextJ, validContextO } from './checks.mjs';
import { validLabelLength, validStringLength } from './lengths.mjs';
import { IDNABidiError, IDNAError, InvalidCodepoint, InvalidCodepointContext, isIDNAError } from './errors.mjs';

/**
 * The label separators recognised in non-strict mode: FULL STOP, IDEOGRAPHIC
 * FULL STOP, FULLWIDTH FULL STOP and HALFWIDTH IDEOGRAPHIC FULL STOP.
 */
const UNICODE_DOTS = /[.。．｡]/;

/**
 * Transitional processing was removed from UTS #46; the reference
 * implementation now warns when the argument is set. The flag has no effect
 * unless UTS #46 remapping is also requested, which this program never does.
 */
function warnTransitional(transitional) {
  if (transitional) {
    process.emitWarning(
      'Transitional processing has been removed from UTS #46. The transitional argument will be removed in a future version.',
      'DeprecationWarning'
    );
  }
}

/**
 * @param {string} s
 * @param {{strict?: boolean, transitional?: boolean}} [options]
 * @returns {string} the encoded domain as ASCII octets
 * @throws {IDNAError}
 */
export function encode(s, options = {}) {
  const { strict = false, transitional = false } = options;
  warnTransitional(transitional);

  const labels = strict ? s.split('.') : s.split(UNICODE_DOTS);
  if (labels.length === 0 || (labels.length === 1 && labels[0] === '')) {
    throw new IDNAError('Empty domain');
  }

  let trailingDot = false;
  if (labels[labels.length - 1] === '') {
    labels.pop();
    trailingDot = true;
  }

  const result = [];
  for (const label of labels) {
    const encoded = alabel(label);
    if (encoded) result.push(encoded);
    else throw new IDNAError('Empty label');
  }
  if (trailingDot) result.push('');

  const joined = result.join('.');
  if (!validStringLength(joined, trailingDot)) throw new IDNAError('Domain too long');
  return joined;
}

/**
 * @param {string} s
 * @param {{strict?: boolean}} [options]
 * @returns {string} the decoded Unicode domain
 * @throws {IDNAError}
 */
export function decode(s, options = {}) {
  const { strict = false } = options;

  const labels = strict ? s.split('.') : s.split(UNICODE_DOTS);
  if (labels.length === 0 || (labels.length === 1 && labels[0] === '')) {
    throw new IDNAError('Empty domain');
  }

  let trailingDot = false;
  if (!labels[labels.length - 1]) {
    labels.pop();
    trailingDot = true;
  }

  const result = [];
  for (const label of labels) {
    const decoded = ulabel(label);
    if (decoded) result.push(decoded);
    else throw new IDNAError('Empty label');
  }
  if (trailingDot) result.push('');

  return result.join('.');
}

export {
  alabel,
  ulabel,
  checkBidi,
  checkHyphenOk,
  checkInitialCombiner,
  checkLabel,
  checkNfc,
  validContextJ,
  validContextO,
  validLabelLength,
  validStringLength,
  IDNAError,
  IDNABidiError,
  InvalidCodepoint,
  InvalidCodepointContext,
  isIDNAError,
};

/**
 * Mirror of the reference package's `idna.core` submodule, so callers can reach
 * the exception types the same way.
 */
export const core = {
  encode,
  decode,
  alabel,
  ulabel,
  checkBidi,
  checkHyphenOk,
  checkInitialCombiner,
  checkLabel,
  checkNfc,
  validContextJ,
  validContextO,
  validLabelLength,
  validStringLength,
  IDNAError,
  IDNABidiError,
  InvalidCodepoint,
  InvalidCodepointContext,
};
